import sys, threading, time
sys.path.insert(0, 'src')
import worker

# Try to induce a real deadlock with the actual lock ordering
p = worker.Pool()
for j in range(200):
    p.submit(j)

def worker_fn(wid):
    for _ in range(500):
        p.claim(wid)
        p.handoff(wid, None)

threads = [threading.Thread(target=worker_fn, args=(f"w{i}",)) for i in range(8)]
for t in threads: t.start()
for t in threads: t.join(timeout=10)
alive = [t.name for t in threads if t.is_alive()]
print("threads still alive after 10s:", alive)
print("queue left:", len(p._queue), "reports:", len(p._reports))

# Now stress handoff-first drain with concurrency
p2 = worker.Pool()
for j in range(200):
    p2.submit(j)
stop = threading.Event()
def handoff_fn(wid):
    while not stop.is_set():
        r = p2.handoff(wid, j)
        if r is None:
            break
j = 1
threads = [threading.Thread(target=handoff_fn, args=(f"h{i}",)) for i in range(4)]
for t in threads: t.start()
for t in threads: t.join(timeout=10)
alive = [t.name for t in threads if t.is_alive()]
print("handoff threads still alive:", alive)
print("queue left:", len(p2._queue))
